insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'thym-citron'), 'infusion', 'Infusion de thym citron', '1 cuillère à café de feuilles séchées ou quelques brins frais pour 150 ml d''eau frémissante. Couvrir 10 minutes, filtrer.', null, 0);
insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'thym-citron'), 'cuisine', 'En cuisine', 'Parfait sur le poisson, les légumes rôtis et dans les marinades citronnées.', null, 1);
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'thym-citron'), 'contre-indication', 'attention', 'Allergie aux Lamiacées possible.');
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'thym-citron'), 'precaution', 'attention', 'Huile essentielle : usage réservé aux professionnels ; l''usage culinaire reste possible.');
insert into public.herbs (slug, common_name, scientific_name, family, summary, parts_used, active_principles, harvest_months, published) values ('fleurs-de-sureau', 'Fleurs de sureau', 'Sambucus nigra', 'Adoxacées', 'Ombelles crémeuses au parfum de miel de juin, bases des beignets et sirops de grand-mère.', array['Fleurs']::text[], array['Flavonoïdes','Acides phénoliques']::text[], array[6,7]::int[], true) on conflict (slug) do nothing;
insert into public.benefits (herb_id, symptom_id, description, evidence_level) values ((select id from public.herbs where slug = 'fleurs-de-sureau'), (select id from public.symptoms where slug = 'voies-respiratoires'), 'Tisane traditionnelle des refroidissements, souvent adoucie d''une cuillère de miel ; en gargarisme tiède pour la gorge.', 'traditionnel') on conflict do nothing;
insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'fleurs-de-sureau'), 'infusion', 'Tisane de fleurs', '1 cuillère à soupe de fleurs séchées (ou 2 de fraîches, bien égrenées) pour 250 ml d''eau frémissante. Couvrir 10 minutes, filtrer.', 'Parfait avec une cuillère de miel.', 0);
insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'fleurs-de-sureau'), 'cuisine', 'Sirop et beignets', 'Sirop de fleurs, limonade maison ou beignets : bien cuire les préparations, toujours.', null, 1);
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'fleurs-de-sureau'), 'precaution', 'danger', 'Baies et parties vertes crues : toxiques (nausées, vomissements). Utilisez uniquement les fleurs, et cuisez systématiquement les préparations.');
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'fleurs-de-sureau'), 'precaution', 'attention', 'Identification certaine obligatoire avant toute cueillette (confusion possible avec d''autres arbustes).');
insert into public.herbs (slug, common_name, scientific_name, family, summary, parts_used, active_principles, harvest_months, published) values ('mauve', 'Mauve', 'Malva sylvestris', 'Malvacées', 'Fleurs mauves et feuilles douces, très mucilagineuses : la tisane gorgée de douceur.', array['Fleurs','Feuilles']::text[], array['Mucilages','Anthocyanes']::text[], array[4,5,6,7,8,9]::int[], true) on conflict (slug) do nothing;
insert into public.benefits (herb_id, symptom_id, description, evidence_level) values ((select id from public.herbs where slug = 'mauve'), (select id from public.symptoms where slug = 'voies-respiratoires'), 'Traditionnellement utilisée en tisane pour adoucir la gorge irritée.', 'traditionnel') on conflict do nothing;
insert into public.benefits (herb_id, symptom_id, description, evidence_level) values ((select id from public.herbs where slug = 'mauve'), (select id from public.symptoms where slug = 'digestion'), 'Les mucilages sont traditionnellement associés à l''apaisement des muqueuses digestives.', 'traditionnel') on conflict do nothing;
insert into public.benefits (herb_id, symptom_id, description, evidence_level) values ((select id from public.herbs where slug = 'mauve'), (select id from public.symptoms where slug = 'confort-urinaire'), 'Employée traditionnellement en tisane douce lors des inconforts urinaires passagers.', 'traditionnel') on conflict do nothing;
insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'mauve'), 'infusion', 'Tisane de mauve', '1 à 2 cuillères à café de fleurs et feuilles séchées pour 150 ml d''eau chaude. Couvrir 10 minutes, filtrer.', 'L''infusion est légèrement gluante : c''est le signe des mucilages.', 0);
insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'mauve'), 'cuisine', 'En cuisine', 'Jeunes feuilles dans les salades et les soupes ; fleurs comestibles en décor.', null, 1);
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'mauve'), 'precaution', 'info', 'Aucune précaution particulière connue pour l''usage traditionnel occasionnel.');
insert into public.herbs (slug, common_name, scientific_name, family, summary, parts_used, active_principles, harvest_months, published) values ('ail-des-ours', 'Ail des ours', 'Allium ursinum', 'Amaryllidacées', 'Oignon sauvage des sous-bois au parfum d''ail doux, star des cueillettes de printemps.', array['Feuilles','Fleurs','Bulbe']::text[], array['Composés soufrés','Flavonoïdes']::text[], array[3,4,5]::int[], true) on conflict (slug) do nothing;
insert into public.benefits (herb_id, symptom_id, description, evidence_level) values ((select id from public.herbs where slug = 'ail-des-ours'), (select id from public.symptoms where slug = 'digestion'), 'Traditionnellement utilisé comme condiment printanier pour soutenir la digestion.', 'traditionnel') on conflict do nothing;
insert into public.benefits (herb_id, symptom_id, description, evidence_level) values ((select id from public.herbs where slug = 'ail-des-ours'), (select id from public.symptoms where slug = 'voies-respiratoires'), 'Employé traditionnellement en cures de feuilles fraîches lors des rhumes de printemps.', 'traditionnel') on conflict do nothing;
insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'ail-des-ours'), 'cuisine', 'Pesto d''ail des ours', 'Feuilles lavées, parmesan, noix et huile d''olive : mixez, gardez au frais et consommez rapidement.', 'Ciselé cru, il remplace partout l''ail classique, avec plus de douceur.', 0);
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'ail-des-ours'), 'precaution', 'danger', 'Confusion mortelle possible avec le muguet ou la colchique : récoltez uniquement avec une identification certaine (odeur d''ail en frottant la feuille, jamais une seule caractéristique), ou achetez de jeunes plants.');
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'ail-des-ours'), 'precaution', 'attention', 'Commencez doucement : les feuilles crues en grande quantité peuvent irriter l''estomac.');
insert into public.herbs (slug, common_name, scientific_name, family, summary, parts_used, active_principles, harvest_months, published) values ('bleuet', 'Bleuet', 'Centaurea cyanus', 'Astéracées', 'Fleurs d''un bleu intense des moissons, comestibles et décoratives.', array['Fleurs']::text[], array['Anthocyanes','Composés phénoliques']::text[], array[5,6,7,8]::int[], true) on conflict (slug) do nothing;
insert into public.benefits (herb_id, symptom_id, description, evidence_level) values ((select id from public.herbs where slug = 'bleuet'), (select id from public.symptoms where slug = 'stress-sommeil'), 'Employé traditionnellement en tisane légère pour la détente.', 'traditionnel') on conflict do nothing;
insert into public.benefits (herb_id, symptom_id, description, evidence_level) values ((select id from public.herbs where slug = 'bleuet'), (select id from public.symptoms where slug = 'confort-urinaire'), 'Traditionnellement associé au confort urinaire dans l''herboristerie populaire.', 'traditionnel') on conflict do nothing;
insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'bleuet'), 'infusion', 'Tisane de fleurs', '1 cuillère à café de fleurs séchées pour 150 ml d''eau chaude, 5 à 10 minutes, filtrer.', null, 0);
insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'bleuet'), 'cuisine', 'Fleurs comestibles', 'Pétales sur les salades, les glaces et les pâtisseries ; en infusion mélangée au thé.', null, 1);
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'bleuet'), 'contre-indication', 'attention', 'Allergie aux Astéracées possible.');
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'bleuet'), 'precaution', 'info', 'Choisissez des fleurs issues de cultures sans traitement chimique.');
insert into public.herbs (slug, common_name, scientific_name, family, summary, parts_used, active_principles, harvest_months, published) values ('fenugrec', 'Fenugrec', 'Trigonella foenum-graecum', 'Fabacées', 'Graines épicées au parfum de caramel brûlé, pilier des currys et des mélanges indiens.', array['Graines','Feuilles (methi)']::text[], array['Saponines','4-hydroxyisoleucine','Protéines']::text[], array[6,7,8,9]::int[], true) on conflict (slug) do nothing;
insert into public.benefits (herb_id, symptom_id, description, evidence_level) values ((select id from public.herbs where slug = 'fenugrec'), (select id from public.symptoms where slug = 'digestion'), 'Traditionnellement employé pour stimuler l''appétit et soutenir la digestion.', 'traditionnel') on conflict do nothing;
insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'fenugrec'), 'cuisine', 'Graines torréfiées', 'Torréfieez à sec puis moulez ; trempées une nuit, elles deviennent plus douces.', null, 0);
insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'fenugrec'), 'infusion', 'Infusion de graines', '1 cuillère à café de graines écrasées pour 150 ml d''eau chaude, 10 minutes, filtrer.', null, 1);
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'fenugrec'), 'precaution', 'attention', 'Grossesse : évitez les usages médicinaux ; l''usage culinaire reste possible.');
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'fenugrec'), 'interaction', 'attention', 'Traitement du diabète ou de la thyroïde : interactions possibles, demandez un avis médical.');
insert into public.herbs (slug, common_name, scientific_name, family, summary, parts_used, active_principles, harvest_months, published) values ('bourrache', 'Bourrache', 'Borago officinalis', 'Boraginacées', 'Fleurs étoilées bleues comestibles et mellifères, au feuillage rugueux au goût d''huître.', array['Fleurs','Jeunes feuilles']::text[], array['Mucilages','Acide gamma-linolénique (huile de graines)']::text[], array[5,6,7,8,9]::int[], true) on conflict (slug) do nothing;
insert into public.benefits (herb_id, symptom_id, description, evidence_level) values ((select id from public.herbs where slug = 'bourrache'), (select id from public.symptoms where slug = 'confort-urinaire'), 'Traditionnellement employée en tisane douce lors des cures printanières de confort urinaire.', 'traditionnel') on conflict do nothing;
insert into public.benefits (herb_id, symptom_id, description, evidence_level) values ((select id from public.herbs where slug = 'bourrache'), (select id from public.symptoms where slug = 'digestion'), 'Jeunes feuilles cuites, traditionnellement consommées comme légume vert.', 'traditionnel') on conflict do nothing;
insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'bourrache'), 'cuisine', 'Fleurs et jeunes feuilles', 'Fleurs sur les salades et les desserts ; jeunes feuilles cuites comme des épinards, en faible quantité.', null, 0);
insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'bourrache'), 'infusion', 'Tisane de fleurs', '1 cuillère à café de fleurs séchées pour 150 ml d''eau chaude, 10 minutes, filtrer.', null, 1);
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'bourrache'), 'precaution', 'danger', 'Les parties aériennes contiennent de petites quantités d''alcaloïdes pyrrolizidiniques (hépatotoxiques) : limitez la quantité et la durée, évitez les cures prolongées et les extraits concentrés.');
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'bourrache'), 'precaution', 'attention', 'Grossesse, allaitement, enfants : évitez les usages internes réguliers.');
insert into public.tips (slug, category, title, body) values ('menthe-en-pot', 'culture', 'Cultiver la menthe en pot', 'La menthe est envahissante : plantez-la dans un pot ou un seau enterré. Sol frais, mi-ombre, arrosage régulier. Taillez souvent pour garder un feuillage tendre.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('thym-soleil', 'culture', 'Un thym heureux : soleil et drainage', 'Plein soleil, sol pauvre et très drainant, peu d''eau. Taillez légèrement après la floraison pour éviter qu''il ne se dégarnisse.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('basilic-chaleur', 'culture', 'Réussir son basilic', 'Semez après les derniers gels, au chaud et en plein soleil. Pincez les têtes pour le faire ramifier et retirez les boutons floraux pour prolonger la récolte.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('persil-germination', 'culture', 'Faire germer le persil', 'Sa germination est lente (3 à 6 semaines). Semez en place dans un sol frais, car il supporte mal la transplantation.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('romarin-hiver', 'culture', 'Romarin : sec et ensoleillé', 'Il craint l''excès d''eau plus que le froid. Offrez-lui un sol drainant ; en pot, évitez la soucoupe pleine en hiver.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('secher-herbes', 'conservation', 'Sécher ses herbes', 'Récoltez le matin après la rosée, puis suspendez-les en petits bouquets, à l''ombre dans un endroit aéré. Conservez-les dans des bocaux opaques, loin de la chaleur et de l''humidité.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('glacons-herbes', 'conservation', 'Congeler en glaçons', 'Hachez des herbes tendres (menthe, mélisse, persil, ciboulette), répartissez-les dans un bac à glaçons, couvrez d''eau ou d''huile d''olive et congelez.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('tiges-eau', 'conservation', 'Garder les herbes fraîches au frigo', 'Les herbes tendres (persil, coriandre, menthe) tiennent plus longtemps debout dans un verre d''eau, au frais. Le basilic, lui, déteste le froid : gardez-le à température ambiante.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('labelliser', 'conservation', 'Étiqueter et dater', 'Notez le nom et la date de séchage sur chaque bocal. Les herbes séchées gardent leurs arômes environ un an ; au-delà, renouvelez-les.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('infusion-couvrir', 'quotidien', 'Une infusion réussie', 'Couvrez la tasse pendant l''infusion pour garder les huiles volatiles, et utilisez une eau frémissante plutôt que bouillante pour les feuilles tendres.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('fraiches-ou-seches', 'quotidien', 'Fraîches ou sèches ?', 'Les herbes robustes (thym, romarin, laurier, origan) s''ajoutent en début de cuisson. Les herbes tendres (basilic, persil, ciboulette, cerfeuil) se glissent à la fin.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('pas-de-cueillette-sauvage', 'quotidien', 'Cueillette sauvage : prudence', 'Certaines plantes toxiques ressemblent à des herbes comestibles (ciguë et cerfeuil, laurier-rose et laurier-sauce). N''utilisez que des plantes identifiées avec certitude.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('avis-pro', 'quotidien', 'Quand demander conseil', 'Grossesse, allaitement, enfants, traitement en cours ou maladie chronique : parlez-en à votre médecin ou à votre pharmacien avant tout usage médicinal régulier.') on conflict (slug) do nothing;
